  <h5 class="grid-linha-tempo-descricao-h5"><strong>{{dataItem.nome}}</strong>
    <span class="aviso-periodo-pauta-finalizado-linha-tempo"
      ng-if="textoContem(dataItem.descricao,'Período de Pauta finalizado com sucesso')">
      <span class="glyphicon glyphicon-ok"></span> Finalizado</span>

    <span class="situacao-emenda-rejeitada" ng-if="textoContem(dataItem.emenda.situacao,'REJEITADA')">
      <span class="glyphicon glyphicon-remove"></span> Rejeitada</span>

    <span class="situacao-emenda-aprovada" ng-if="textoContem(dataItem.emenda.situacao,'APROVADA')">
      <span class="glyphicon glyphicon-ok"></span> Aprovada</span>
  </h5>

  <p class="texto-ementa-card" ng-init="criarDescricaoCompilada(dataItem); carregarObservacoesDosVotos(dataItem)"></p>

  <p class="descricao-linha-tempo" ng-if="dataItem.exibirDescricaoCompleta"
    ng-bind-html="dataItem.descricaoCompletaCompilado"></p>

  <p class="descricao-linha-tempo" ng-if="!dataItem.exibirDescricaoCompleta"
    ng-bind-html="dataItem.descricaoImcompletoCompilado"></p>

  <a ng-show="dataItem.descricao.length > lengthContinuarLendo"
    ng-click="dataItem.exibirDescricaoCompleta = !dataItem.exibirDescricaoCompleta">
    {{dataItem.exibirDescricaoCompleta ? 'Mostrar menos' : 'Continuar lendo'}}</a>

  <div class="observacoes-votos"
    ng-if="dataItem.exibirDescricaoCompleta && (dataItem.observacaoPublicaVotacao || (dataItem.recibos && dataItem.recibos.length))">
    <p class="observacoes-votos__titulo"
      ng-class="{'observacoes-votos__titulo_com-itens': dataItem.recibos && dataItem.recibos.length}">
      <strong>Observações:</strong>
      <span ng-if="dataItem.observacaoPublicaVotacao"> {{dataItem.observacaoPublicaVotacao}}</span>
    </p>
    <p class="observacoes-votos__item" ng-repeat="recibo in dataItem.recibos">
      <strong>{{recibo.proponente.nome}}:</strong>
      <span>{{recibo.observacao}}</span>
    </p>
  </div>

  <br>
  <div class="adicionais-grid-linha-tempo"
    ng-class="{'adicionais-grid-linha-tempo_padding': exibirBotaoRelatorio(dataItem) || dataItem.anexos.length > 0}">
    <span ng-if="exibirBotaoRelatorio(dataItem) && isMostrarRelatorio(dataItem.tipo)">
      <a ng-click="visualizarRelatorio(dataItem)" data-cy="btn-imprimir-relatorio">
        {{ exibirTextoBotaoDeRelatorio(dataItem) }}
      </a>
      <span class="grid-linha-tempo-descricao__separador" ng-if="isMostrarAnexos(dataItem)"> | </span>
    </span>
    <span ng-if="isMostrarAnexos(dataItem)" ng-repeat="anexo in dataItem.anexos"
      class="listview-linha-tempo-descricao__inline listview-linha-tempo-descricao_anexos">
      <a download href="hal/public/arquivos?uri={{anexo.uri}}&thumbnail=false">
        <span class="glyphicon glyphicon-save-file" ng-if="anexo.nome"></span>
        {{anexo.nome}}
      </a>
    </span>
