  <ul class="nav nav-tabs">
    <li class="tabs-pesquisa" role="presentation" ng-click="controlTabs('rapida')"
      ng-class="{active : tabAtual === 'rapida'}" ng-init="tabAtual = 'rapida'">
      <a>Pesquisa Rápida</a>
    </li>
    <li class="tabs-pesquisa" role="presentation" ng-click="controlTabs('avancada')"
      ng-class="{active : tabAtual === 'avancada'}">
      <a>Pesquisa Avançada</a>
    </li>
  </ul>

  \x3c!--++++++++++++++++++++++++++++++++++++++++++++++++++++--\x3e
  \x3c!--+++++++++++++++++Pesquisa Rápida++++++++++++++++++++--\x3e
  \x3c!--++++++++++++++++++++++++++++++++++++++++++++++++++++--\x3e
  <div class='tabRapida' ng-show="tabAtual === 'rapida'">

    <br><br>
    <div class="row">
      <div class="col-md-3">
        <h5>&nbsp;</h5>
        <input id="textoIntegralInput" type="text" class="form-control " ng-model="proposicaoFilterRapido.textoIntegral"
          placeholder="Digite o que está procurando" aria-describedby="basic-addon2"
          ng-keypress="teclaPressionada($event, 'searchRapido')">
      </div>
      <div class="col-md-3">
        <h5>Autoria</h5>
        <select kendo-combo-box id="comboAutores" ng-model="proposicaoFilterRapido.idAutor" k-placeholder="'Selecione'"
          k-data-text-field="'nome'" k-data-value-field="'id'" k-filter="'contains'" k-auto-bind="false"
          k-options="autoriaOptions" class="sgpub-combobox" ng-keypress="teclaPressionada($event, 'searchRapido')">
        </select>
      </div>
      <div class="col-md-3">
        <h5>Tipo de Proposição</h5>
        <select kendo-combo-box id="comboTipoProposicao" ng-model="proposicaoFilterRapido.idTipoProposicao"
          k-placeholder="'Selecione'" k-data-text-field="'descricao'" k-data-value-field="'id'" k-filter="'contains'"
          k-auto-bind="false" k-data-source="tiposProposicao" class="sgpub-combobox"
          ng-keypress="teclaPressionada($event, 'searchRapido')">
        </select>
      </div>
      <div class="col-md-3">
        <h5>Assunto</h5>
        <select kendo-combo-box id="comboAssunto" ng-model="proposicaoFilterRapido.idAssunto"
          k-placeholder="'Selecione'" k-data-text-field="'descricao'" k-data-value-field="'id'" k-filter="'contains'"
          k-auto-bind="false" k-data-source="assuntos" class="sgpub-combobox"
          ng-keypress="teclaPressionada($event, 'searchRapido')">
        </select>
      </div>
    </div>
    <div class="row">
      <div class="col-md-6">
        <p class="label-under-pesquisa">Exemplo de busca: "escola", "transporte", e etc...</p>
        <div class="button-container" style="margin-top: 10px;">
          <button type="button" class="btn btn-default" style="margin-right: 10px; padding: 5px 20px;"
            ng-click="addTextoFiltroSimples('E')">E</button>
          <button type="button" class="btn btn-default" style="margin-right: 10px; padding: 5px 15px;"
            ng-click="addTextoFiltroSimples('OU')">OU</button>
          <button type="button" class="btn btn-default" style="margin-right: 10px; padding: 5px 10px;"
            ng-click="addTextoFiltroSimples('NÃO')">NÃO</button>
        </div>
      </div>
      <div class="col-md-6">
        <h5>&nbsp;</h5>
        <div class="limpar-filtros">
          <button id="limparFiltrosRapidoId" class="sgpub-btn sgpub-btn-danger" ng-click="clearFilters()" role="button">
            Limpar filtros
          </button>
          <button id="buscarFiltrosRapidoId" class="sgpub-btn sgpub-btn-success" ng-click="searchRapido()"
            role="button">
            Pesquisar
          </button>

        </div>
      </div>
    </div>
  </div>

  \x3c!--++++++++++++++++++++++++++++++++++++++++++++++++++++++--\x3e
  \x3c!--+++++++++++++++++Pesquisa Avançada++++++++++++++++++++--\x3e
  \x3c!--++++++++++++++++++++++++++++++++++++++++++++++++++++++--\x3e
  <div ng-show="tabAtual === 'avancada'" kendo-validator="validador">
    <div class="aba-pesquisa-avancada">
      <br><br>
      <div class="row">
        <div class="col-md-4">
          <sg-combo-com-input id="typeOfNumber" name="typeOfNumber" select-label="Tipo" select-ng-model="typeOfNumber"
            select-datasource="opcoesFiltroNumero" select-text-field="value" select-value-field="id"
            select-placeholder="Selecione" select-required="number !== '' && number !== null && number !== undefined"
            input-label="{{typeOfNumber === 'NUMERO_OFICIO'? 'Número do Ofício' : 'Número'}}"
            input-required="typeOfNumber" input-is-mask="typeOfNumber !== 'NUMERO_OFICIO'" input-maskformat="00000/0000"
            input-pattern="[0-9]{5}/[0-9]{4}" input-ng-model="number" input-tooltip="tooltipNumber"
            ng-keypress="teclaPressionada($event)">
          </sg-combo-com-input>
        </div>

        <div class="col-md-4">
          <sg-combo-com-input id="typeOfText" name="typeOfText" select-label="Tipo do Texto"
            select-ng-model="typeOfText" select-datasource="opcoesFiltroTexto" select-text-field="value"
            select-value-field="id" select-placeholder="Selecione" select-required="keyWord" input-label="Palavra-Chave"
            input-required="typeOfText" input-is-mask="false" input-ng-model="keyWord" input-tooltip="tooltipKeyWord"
            ng-keypress="teclaPressionada($event)">
          </sg-combo-com-input>
          <div class="button-container" style="margin-top: 5px; left: 45%; position: absolute; z-index: 10;">
            <button type="button" class="btn btn-default" style="margin-right: 5px; padding: 0px 20px;"
              ng-click="addTextoFiltroAvancado('E')">E</button>
            <button type="button" class="btn btn-default" style="margin-right: 5px; padding: 0px 15px;"
              ng-click="addTextoFiltroAvancado('OU')">OU</button>
            <button type="button" class="btn btn-default" style="margin-right: 5px; padding: 0px 10px;"
              ng-click="addTextoFiltroAvancado('NÃO')">NÃO</button>
          </div>
        </div>

        <div class="col-md-4">
          <h5>Situação</h5>
          <select kendo-combo-box id="comboSituacao" ng-model="proposicaoFilter.idSituacao" k-placeholder="'Selecione'"
            k-data-text-field="'descricao'" k-data-value-field="'id'" k-filter="'contains'" k-auto-bind="false"
            k-data-source="situacoes" class="sgpub-combobox" ng-keypress="teclaPressionada($event, 'search')">
          </select>
        </div>
      </div>

      <div class="row">
        <div class="col-md-4">
          <h5>Tipo de Proposição</h5>
          <select kendo-combo-box id="tipoProposicao" ng-model="proposicaoFilter.idTipoProposicao"
            k-placeholder="'Selecione'" k-data-text-field="'descricao'" k-data-value-field="'id'" k-filter="'contains'"
            k-auto-bind="false" k-data-source="tiposProposicao" class="sgpub-combobox"
            ng-keypress="teclaPressionada($event, 'search')">
          </select>
        </div>
        <div class="col-md-4">
          <az-smalltext id="sigla" ng-model="proposicaoFilter.sigla" label="Sigla"
            label-class="az-filtro__cabecalho_rotulo" placeholder="Informe a Sigla"
            ng-keypress="teclaPressionada($event)">
          </az-smalltext>
        </div>

        <div class="col-md-4">
          <h5>Assunto</h5>
          <select kendo-combo-box id="idAssunto" ng-model="proposicaoFilter.idAssunto" k-placeholder="'Selecione'"
            k-data-text-field="'descricao'" k-data-value-field="'id'" k-filter="'contains'" k-auto-bind="false"
            k-data-source="assuntos" class="sgpub-combobox" ng-keypress="teclaPressionada($event, 'searchRapido')">
          </select>
        </div>
      </div>

      <div class="row">
        <div class="col-md-4">
          <h5>Autor</h5>
          <select kendo-combo-box id="idAutor" ng-model="proposicaoFilter.idAutor" k-placeholder="'Selecione'"
            k-data-text-field="'nome'" k-data-value-field="'id'" k-filter="'contains'" k-auto-bind="false"
            k-options="autoriaOptions" class="sgpub-combobox" ng-keypress="teclaPressionada($event, 'search')">
          </select>
        </div>
        <div class="col-md-4">
          <h5>Coautor</h5>
          <select kendo-combo-box id="idCoAutor" ng-model="proposicaoFilter.idCoAutor" k-placeholder="'Selecione'"
            k-data-text-field="'nome'" k-data-value-field="'id'" k-filter="'contains'" k-auto-bind="false"
            k-options="autoriaOptions" class="sgpub-combobox" ng-keypress="teclaPressionada($event, 'search')">
          </select>
        </div>

        <div class="col-md-4">
          <h5>Localidade</h5>
          <select kendo-combo-box id="idMunicipio" ng-model="proposicaoFilter.idMunicipio" k-placeholder="'Selecione'"
            k-data-text-field="'nome'" k-data-value-field="'id'" k-filter="'contains'" k-auto-bind="false"
            k-data-source="localidades" class="sgpub-combobox" ng-keypress="teclaPressionada($event, 'search')">
          </select>
        </div>
      </div>

      <div class="row">
        <div class="col-md-4">
          <label class="az-filtro__cabecalho_rotulo">Data Leitura</label>
          <div class="az-filtro__conteudo">
            <div class="data-leitura-datebox">
              <az-datebox id="dataLeituraInicial" ng-model="proposicaoFilter.dataLeituraInicial"
                container-class="sl-filtro-data-inicial"
                ng-change="validateDateRange(proposicaoFilter.dataLeituraInicial, proposicaoFilter.dataLeituraFinal)"
                datebox-mask ng-keypress="teclaPressionada($event)">
              </az-datebox>
              <span class="a-craseado-datebox">à</span>
              <az-datebox id="dataLeituraFinal" ng-model="proposicaoFilter.dataLeituraFinal"
                container-class="sl-filtro-data-final"
                ng-change="validateDateRange(proposicaoFilter.dataLeituraInicial, proposicaoFilter.dataLeituraFinal)"
                datebox-mask ng-keypress="teclaPressionada($event)">
              </az-datebox>
            </div>
          </div>
        </div>
        <div class="col-md-8">
          <div class="comandos-busca">
            <div class="limpar-filtros">
              <button id="limparFiltrosId" class="sgpub-btn sgpub-btn-danger" ng-click="clearFilters()" role="button">
                Limpar filtros
              </button>
              <button id="buscarFiltrosId" class="sgpub-btn sgpub-btn-success" ng-click="search()" role="button">
                Pesquisar
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <hr class="line-grid" />
  <div class="spgpub-grid">
    <div ng-if="!pesquisaRealizada" class="alert alert-info" style="margin: 20px; padding: 15px; text-align: center;">
      <strong>Por favor, realize uma pesquisa para visualizar os resultados.</strong>
    </div>
    <div ng-if="pesquisaRealizada" id="grid-busca-proposicao" kendo-grid="mainGrid" k-options="mainGridOptions">
