body {
  height: 100%;
  margin: 0;
  padding: 0;
  background: #f3f3f3;
}
.imagem-alms {
  background-color: #fff;
  border-bottom: 1px solid #e0e0e0;
  padding: 0;
}
.sgpub-container {
  height: 100%;
}
.sgpub-container__footer {
  box-sizing: border-box;
  margin-top: 70px;
  padding: 15px 0;
  background: #263238;
  border-top: 1px solid #dee5e7;
  width: 100%;
  height: 50px;
}
.sgpub-container__footer p {
  margin: 0;
  font-size: 12px;
  color: #ffffff;
}
@media (max-width: 480px) {
  .sgpub-container {
    margin: 0 auto -65px;
  }
  .sgpub-container__footer {
    height: 65px;
  }
  .sgpub-container__footer p {
    text-align: center;
  }
  .sgpub-container__footer .text-center {
    display: none;
